import CreatExpandContainer from '../../utils/CreatExpandContainer.js';

import { Utils as PhaserUtils } from 'phaser';
const GetValue = PhaserUtils.Objects.GetValue;

var LayoutMode1 = function (config) {
    var scene = this.scene;
    var indexLabel = config.indexLabel;
    var displayNameLabel = config.displayNameLabel;
    var deleteButton = config.deleteButton;
    var space = config.space || {};

    this.orientation = 1;

    var header = CreatExpandContainer(scene, 0);
    this.add(
        header,
        {
            proportion: 0, expand: true,
            padding: {
                bottom: GetValue(space, 'index', 0)
            }
        }
    )

    header
        .add(
            indexLabel,
            {
                proportion: 0, expand: true,

            }
        )
        .addSpace()
        .add(
            deleteButton,
            {
                proportion: 0, expand: true,
            }
        )

    this.add(
        displayNameLabel,
        {
            proportion: 1, expand: true,
        }
    );
}

export default LayoutMode1;